{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- Before any action that changes a booking (`cancel_booking`, `change_vehicle_class`, `add_driver`, `issue_refund`), state the details and obtain explicit confirmation (\"yes\"/\"да\").",
      "requirement": "The assistant must explicitly confirm the cancellation details with the user before executing the `cancel_booking` tool call."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- A booking can be cancelled with `cancel_booking`. The cancellation fee depends on the time remaining until `pickup_time`:\n  - 48 hours or more before pickup: no fee (`fee_usd` = 0);\n  - less than 48 hours before pickup: a fee of 50 USD (`fee_usd` = 50).\n- Exception: customers with `tier` equal to `gold` never pay a cancellation fee (`fee_usd` = 0), regardless of timing.",
      "requirement": "The cancellation fee must be set to `0` if the booking is cancelled 48+ hours before pickup or if the customer's tier is `gold`. Otherwise, the fee must be `50`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- The fee is charged automatically by the system to the booking's payment method; you must pass the correct `fee_usd`.",
      "requirement": "The `fee_usd` argument in the `cancel_booking` tool call must match the calculated cancellation fee for the booking."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- You may only act on bookings listed in that customer's profile.",
      "requirement": "The booking being cancelled must belong to the customer whose ID was verified via `get_customer`."
    }
  ]
}
